18	// Use 64-byte alignment to match common HTIF implementations and ensure
19	// they fall on separate cache lines/bursts if needed.
20	extern "C" {
21	volatile uint64_t tohost __attribute__((section(".htif"), aligned(64), used)) =
22	    0;
23	volatile uint64_t fromhost
24	    __attribute__((section(".htif"), aligned(64), used)) = 0;
25	volatile uint64_t tohost_ready
26	    __attribute__((section(".htif"), aligned(64), used)) = 0;
27	volatile uint64_t fromhost_ready
28	    __attribute__((section(".htif"), aligned(64), used)) = 0;
