30	long htif_syscall_6args(long n, long a0, long a1, long a2, long a3, long a4,
31	                        long a5) {
32	  volatile uint64_t buf[8];
33	  buf[0] = n;
34	  buf[1] = a0;
35	  buf[2] = a1;
36	  buf[3] = a2;
37	  buf[4] = a3;
38	  buf[5] = a4;
39	  buf[6] = a5;
40	  buf[7] = 0;
41	
42	  // HTIF protocol: write packet address to tohost.
43	  // For RV32, we write the 32-bit address.
44	  // The testbench should read it as a 64-bit value.
45	
46	  // Memory fence to ensure buf is written before tohost.
47	  asm volatile("fence rw, w" ::: "memory");
48	
49	  tohost = (uintptr_t)buf;
50	
51	  // For compatibility with systems requiring a ready signal (like MPACT),
52	  // write to tohost_ready after setting the payload in tohost.
53	  asm volatile("fence rw, w" ::: "memory");
54	  tohost_ready = 1;
55	
56	  // Poll for completion. We check both fromhost (standard Spike/HTIF)
57	  // and fromhost_ready (MPACT-style) for broad compatibility.
58	  while (fromhost == 0 && fromhost_ready == 0);
59	  fromhost = 0;
60	  fromhost_ready = 0;
61	
62	  asm volatile("fence r, rw" ::: "memory");
63	  return buf[0];
64	}
