134	  extern char __heap_start__, __heap_end__;
135	  static char* _heap_ptr = &__heap_start__;
136	  char* prev_heap_end;
137	  if ((bytes < 0) || (_heap_ptr + bytes > &__heap_end__)) {
138	    errno = ENOMEM;
139	    return reinterpret_cast<void*>(-1);
140	  }
141	
142	  prev_heap_end = _heap_ptr;
143	  _heap_ptr += bytes;
144	
145	  return reinterpret_cast<void*>(prev_heap_end);
146	}
