21	// The guard variable is a 64-bit integer.
22	// The first byte is the flag, 0 = not initialized, 1 = initialized.
23	using __guard = int64_t;
24	
25	extern "C" {
26	
27	// Called to acquire the lock on the guard variable.
28	// *guard_object: Pointer to the guard variable.
29	// Returns 1 if the object should be initialized, 0 otherwise.
30	int __cxa_guard_acquire(__guard* guard_object) {
31	  // If the first byte is 0, initialization is needed.
32	  if (*(reinterpret_cast<char*>(guard_object)) == 0) {
33	    return 1;
34	  }
35	  return 0;
36	}
37	
38	// Called to release the lock on the guard variable after initialization.
39	// *guard_object: Pointer to the guard variable.
40	void __cxa_guard_release(__guard* guard_object) {
41	  // Set the first byte to 1 to indicate initialization is complete.
42	  *(reinterpret_cast<char*>(guard_object)) = 1;
43	}
44	
45	// Called if initialization fails and the guard needs to be aborted.
46	void __cxa_guard_abort(__guard* guard_object) {
47	  // In a bare-metal system, there's not much to do here.
48	  // We can leave it empty or add some debug output if needed.
49	}
