4	// Writes incrementing integers to an array, reads them back and returns the
5	// the accumulated sum.
6	template <typename T, int N>
7	int WriteReadAccumulateArray(volatile T* data) {
8	  for (int i = 0; i < N; i++) {
9	    data[i] = static_cast<T>(i);
10	  }
11	  int acc = 0;
12	  for (int i = 0; i < N; i++) {
13	    acc += data[i];
14	  }
15	  return acc;
16	}
