21	inline uint64_t mcycle_read(void) {
22	  uint32_t cycle_low = 0;
23	  uint32_t cycle_high = 0;
24	  uint32_t cycle_high_2 = 0;
25	  asm volatile(
26	      "1:"
27	      "  csrr %0, mcycleh;"  // Read `mcycleh`.
28	      "  csrr %1, mcycle;"   // Read `mcycle`.
29	      "  csrr %2, mcycleh;"  // Read `mcycleh` again.
30	      "  bne  %0, %2, 1b;"
31	      : "=r"(cycle_high), "=r"(cycle_low), "=r"(cycle_high_2)
32	      :);
33	  return static_cast<uint64_t>(cycle_high) << 32 | cycle_low;
34	}
