43	      "  csrr %1, minstret;"   // Read `minstret`.
44	      "  csrr %2, minstreth;"
45	      "bne %0, %2, 1b;"
46	      : "=r"(instret_high), "=r"(instret_low), "=r"(instret_high_2)
