19	// Assume rhs is column major.
20	void MatMul(size_t lhs_rows, size_t inner, size_t rhs_cols, const int8_t* lhs,
21	            const int8_t* rhs, int32_t* result) {
22	  const size_t vlenb = __riscv_vlenb();
23	
24	  for (size_t r = 0; r < lhs_rows; r++) {
25	    const int8_t* lhs_data = lhs + (r * inner);
26	    int32_t* result_row = result + (r * rhs_cols);
27	    for (size_t c = 0; c < rhs_cols; c++) {
28	      const int8_t* rhs_data = rhs + (c * inner);
29	      // Reset accumulators
30	      vint32m1_t vacc = __riscv_vmv_v_x_i32m1(0, 1);
31	
32	      // Inner dot product loop
33	      size_t k = 0;
34	      size_t vl = vlenb;
35	      while (k < inner) {
36	        if (inner - k < vl) {
37	          vl = inner - k;
38	        }
39	        // Load weights/activations
40	        vint8m1_t vlhs_data = __riscv_vle8_v_i8m1(lhs_data + k, vl);
41	        vint8m1_t vrhs_data =
42	            __riscv_vle8_v_i8m1(rhs_data + k, vl);  // input rhs is transposed
43	        vint16m2_t vmul_16 = __riscv_vwmul_vv_i16m2(vlhs_data, vrhs_data, vl);
44	        vacc = __riscv_vwredsum_vs_i16m2_i32m1(vmul_16, vacc, vlenb);
45	        k += vl;
46	      }
47	      __riscv_vse32_v_i32m1(result_row + c, vacc, 1);
48	    }
49	  }
50	}
